+void HistoryModelTest::testTopSelectionDiffersFromTopClipboard()
+{
+    // Copying something that was not selected as text, a file in Dolphin say, leaves the
+    // selection holding A even though B is the newest entry in the history. Restoring first()
+    // would put B into the selection.
+    seedSelectionAndClipboard();
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+
+    // Calling insert() directly leaves Klipper outside a clipboard update, unlike
+    // checkClipData() which holds the lock. The changed() handler therefore pushes the newest
+    // entry into both buffers and Klipper tracks its own write, so restate what selecting A
+    // and then copying B by other means leaves behind in a real session.
+    history->updateSystemUuids(uuidOf(QStringLiteral("A")), true);
+    history->updateSystemUuids(uuidOf(QStringLiteral("B")), false);
+
+    // B is the newest entry, but the selection still holds A, so restoring first() would put
+    // the wrong entry back into the selection
+    QCOMPARE(history->first()->text(), QStringLiteral("B"));
+    QCOMPARE(history->m_systemClipboardUuid, uuidOf(QStringLiteral("B")));
+    QCOMPARE(history->m_systemSelectionUuid, uuidOf(QStringLiteral("A")));
+
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
+
+void HistoryModelTest::testPickedEntryMarksBothBuffers()
+{
+    seedSelectionAndClipboard();
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+
+    // Picking an entry in Klipper puts it in both buffers
+    history->moveToTop(uuidOf(QStringLiteral("A")));
+    QCOMPARE(history->m_systemSelectionUuid, uuidOf(QStringLiteral("A")));
+    QCOMPARE(history->m_systemClipboardUuid, uuidOf(QStringLiteral("A")));
+
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
+
+void HistoryModelTest::testReinsertDoesNotDuplicate()
+{
+    seedSelectionAndClipboard();
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+
+    // Copying something that is already in the history moves it to the top, it does not add a
+    // second row for it
+    QMimeData clipboard;
+    clipboard.setText(QStringLiteral("A"));
+    QVERIFY(history->insert(&clipboard, 0, false));
+    QCOMPARE(history->rowCount(), 2);
+    QCOMPARE(history->first()->text(), QStringLiteral("A"));
+
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
+
+void HistoryModelTest::testDeletingTheFirstEntryMovesBothBuffers()
+{
+    seedSelectionAndClipboard();
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+    history->updateSystemUuids(uuidOf(QStringLiteral("A")), true);
+    history->updateSystemUuids(uuidOf(QStringLiteral("B")), false);
+
+    // Removing the first entry makes Klipper put the next one in both buffers, so both follow
+    QVERIFY(history->remove(uuidOf(QStringLiteral("B"))));
+    QCOMPARE(history->rowCount(), 1);
+    QCOMPARE(history->m_systemClipboardUuid, uuidOf(QStringLiteral("A")));
+    QCOMPARE(history->m_systemSelectionUuid, uuidOf(QStringLiteral("A")));
+
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
+
+void HistoryModelTest::testDeletingAnotherEntryLeavesTheBuffersAlone()
+{
+    seedSelectionAndClipboard();
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+    history->updateSystemUuids(uuidOf(QStringLiteral("A")), true);
+    history->updateSystemUuids(uuidOf(QStringLiteral("B")), false);
+
+    // Removing an entry that is not the first one leaves both buffers as they were, so the
+    // clipboard still holds B
+    QVERIFY(history->remove(uuidOf(QStringLiteral("A"))));
+    QCOMPARE(history->rowCount(), 1);
+    QCOMPARE(history->m_systemClipboardUuid, uuidOf(QStringLiteral("B")));
+
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
+
+void HistoryModelTest::testSynchronisedPutsOneEntryInBothBuffers()
+{
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+    history->clear();
+    history->setMaxSize(10);
+    writeSetting(QStringLiteral("SaveSelection"), true);
+    writeSetting(QStringLiteral("SyncClipboards"), true);
+
+    // Keeping the selection and the clipboard the same means a selection is in both of them
+    QMimeData selection;
+    selection.setText(QStringLiteral("A"));
+    QVERIFY(history->insert(&selection, 0, true));
+    QCOMPARE(history->m_systemClipboardUuid, uuidOf(QStringLiteral("A")));
+    QCOMPARE(history->m_systemSelectionUuid, uuidOf(QStringLiteral("A")));
+
+    writeSetting(QStringLiteral("SyncClipboards"), false);
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
+
+void HistoryModelTest::testClearForgetsBothBuffers()
+{
+    seedSelectionAndClipboard();
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+    history->updateSystemUuids(uuidOf(QStringLiteral("A")), true);
+    history->updateSystemUuids(uuidOf(QStringLiteral("B")), false);
+
+    // Clearing the history clears both buffers, so neither is remembered any more
+    history->clear();
+    QCOMPARE(history->rowCount(), 0);
+    QVERIFY(history->m_systemClipboardUuid.isEmpty());
+    QVERIFY(history->m_systemSelectionUuid.isEmpty());
+
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
